param([Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][string]$Owner)
$ErrorActionPreference='Stop';$root=$Root;if(!(Test-Path -LiteralPath $root)){@{cleaned=$true;directoryAbsent=$true;alreadyAbsent=$true}|ConvertTo-Json -Compress;exit};$m=Get-Content -LiteralPath (Join-Path $root '.owner.json') -Raw|ConvertFrom-Json;if($m.owner -cne $Owner){throw 'Owned root changed'};$records=@(Get-ChildItem -LiteralPath (Join-Path $root 'profiles') -Filter 'launch-owner-*.json' -Recurse -File -ErrorAction SilentlyContinue);if($records.Count -gt 32){throw 'Owned actor record bound'};foreach($file in $records){$a=Get-Content -LiteralPath $file.FullName -Raw|ConvertFrom-Json;if($a.owner -cne $Owner){throw 'Actor owner mismatch'};try{$p=[Diagnostics.Process]::GetProcessById([int]$a.parentPid)}catch [ArgumentException]{continue};try{$held=$p.Handle;if($p.StartTime.ToFileTimeUtc().ToString() -cne $a.parentFileTime){continue};$c=Get-CimInstance Win32_Process -Filter ('ProcessId='+$a.parentPid);if(!$c -or !$c.ExecutablePath -or $c.ExecutablePath -ine (Join-Path $file.DirectoryName 'launcher.exe')){throw 'Actor image changed'};$p.Kill();if(!$p.WaitForExit(5000)){throw 'Owned launcher did not exit'}}finally{$p.Dispose()}};$f=Join-Path $root 'probe-owner.json';if(Test-Path -LiteralPath $f){$a=Get-Content -LiteralPath $f -Raw|ConvertFrom-Json;if($a.owner -cne $Owner){throw 'Controller owner changed'};try{$p=[Diagnostics.Process]::GetProcessById([int]$a.pid)}catch [ArgumentException]{$p=$null};if($p){try{$held=$p.Handle;if($p.StartTime.ToUniversalTime().Ticks.ToString() -ceq $a.creationTicks){$c=Get-CimInstance Win32_Process -Filter ('ProcessId='+$a.pid);if(!$c.CommandLine.Contains((Join-Path $root 'controller.mjs'))){throw 'Controller command changed'};$p.Kill();[void]$p.WaitForExit(5000)}}finally{$p.Dispose()}}};$deadline=[DateTime]::UtcNow.AddSeconds(15);do{$live=@(Get-CimInstance Win32_Process|Where-Object{$_.ExecutablePath -and $_.ExecutablePath.StartsWith(($root+'\'),[StringComparison]::OrdinalIgnoreCase)});if(!$live.Count){break};Start-Sleep -Milliseconds 100}while([DateTime]::UtcNow -lt $deadline);if($live.Count){throw 'Unsettled owned actors; no delete'};Get-ChildItem -LiteralPath $root -Recurse -Force -File|ForEach-Object{if($_.Attributes -band [IO.FileAttributes]::ReadOnly){$_.IsReadOnly=$false}};[IO.Directory]::Delete($root,$true);@{cleaned=$true;directoryAbsent=!(Test-Path -LiteralPath $root);ownedProcessesAbsent=$true;accountCreated=$false;personalConfigModified=$false}|ConvertTo-Json -Compress
